import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor convtranspose3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int opadD, int opadH, int opadW,
    int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void convtranspose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int kD, int kH, int kW,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int groups,
    int Dout, int Hout, int Wout)
{
  extern __shared__ unsigned char smem_raw[];
  T* smem = reinterpret_cast<T*>(smem_raw);

  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;

  const int n  = blockIdx.z;
  const int oc = blockIdx.y;
  const int g  = oc / Cout_per_group;
  const int oc_local = oc % Cout_per_group;
  const int ic_base  = g * Cin_per_group;

  // Global input tensor for this batch: (Cin, D, H, Win)
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * Cin * D * H * Win),
      make_shape(Cin, D, H, Win),
      make_stride((int64_t)D * H * Win, (int64_t)H * Win, (int64_t)Win, Int<1>{}));

  // Global output tensor for this (n, oc): (Dout, Hout, Wout)
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * Cout * Dout * Hout * Wout + (int64_t)oc * Dout * Hout * Wout),
      make_shape(Dout, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));

  // Global weight tensor: (Cin, Cout_per_group, kD, kH, kW)
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout_per_group, kD, kH, kW),
      make_stride((int64_t)Cout_per_group * kD * kH * kW,
                  (int64_t)kD * kH * kW,
                  (int64_t)kH * kW,
                  (int64_t)kW,
                  Int<1>{}));

  // Shared memory tensor holding weights for this oc: (Cin_per_group, kD, kH, kW)
  auto sW = make_tensor(
      make_smem_ptr(smem),
      make_shape(Cin_per_group, kD, kH, kW),
      make_stride((int64_t)kD * kH * kW, (int64_t)kH * kW, (int64_t)kW, Int<1>{}));

  const int KVOL = kD * kH * kW;
  const int total_w = Cin_per_group * KVOL;

  for (int idx = threadIdx.x; idx < total_w; idx += blockDim.x) {
    int icl  = idx / KVOL;
    int krem = idx % KVOL;
    int kd = krem / (kH * kW);
    int kk = krem % (kH * kW);
    int kh = kk / kW;
    int kw = kk % kW;
    int ic = ic_base + icl;
    sW(icl, kd, kh, kw) = mW(ic, oc_local, kd, kh, kw);
  }
  __syncthreads();

  const int P_total = Dout * Hout * Wout;
  const int p_start = blockIdx.x * blockDim.x;

  for (int p = p_start + threadIdx.x; p < P_total; p += blockDim.x * gridDim.x) {
    int od  = p / (Hout * Wout);
    int rem = p % (Hout * Wout);
    int oh  = rem / Wout;
    int ow  = rem % Wout;

    float acc = 0.0f;

    for (int kd = 0; kd < kD; ++kd) {
      int id_num = od + padD - kd;
      if (id_num % strideD != 0) continue;
      int id = id_num / strideD;
      if (id < 0 || id >= D) continue;

      for (int kh = 0; kh < kH; ++kh) {
        int ih_num = oh + padH - kh;
        if (ih_num % strideH != 0) continue;
        int ih = ih_num / strideH;
        if (ih < 0 || ih >= H) continue;

        for (int kw = 0; kw < kW; ++kw) {
          int iw_num = ow + padW - kw;
          if (iw_num % strideW != 0) continue;
          int iw = iw_num / strideW;
          if (iw < 0 || iw >= Win) continue;

          #pragma unroll 4
          for (int icl = 0; icl < Cin_per_group; ++icl) {
            int ic = ic_base + icl;
            float xval = (float)mX(ic, id, ih, iw);
            float wval = (float)sW(icl, kd, kh, kw);
            acc += xval * wval;
          }
        }
      }
    }

    if (B != nullptr) {
      acc += (float)B[oc];
    }

    mY(od, oh, ow) = static_cast<T>(acc);
  }
}
template <typename T, int TILE_W, int OC_TILE>
__global__ void convtranspose3d_kernel_tiled_s1(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int kD, int kH, int kW,
    int padD, int padH, int padW,
    int groups,
    int Dout, int Hout, int Wout,
    int n_wtiles)
{
  extern __shared__ unsigned char smem_raw[];
  T* smem = reinterpret_cast<T*>(smem_raw);
  const int Cin_per_group  = Cin / groups;
  const int Cout_per_group = Cout / groups;
  const int n  = blockIdx.z;
  const int oc_group = blockIdx.y;
  const int oc_base = oc_group * OC_TILE;
  const int g  = oc_base / Cout_per_group;
  const int oc_local_base = oc_base - g * Cout_per_group;
  const int ic_base  = g * Cin_per_group;
  const int wtile = blockIdx.x % n_wtiles;
  const int tmp = blockIdx.x / n_wtiles;
  const int oh = tmp % Hout;
  const int od = tmp / Hout;
  const int ow0 = wtile * TILE_W;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * Cin * D * H * Win),
      make_shape(Cin, D, H, Win),
      make_stride((int64_t)D * H * Win, (int64_t)H * Win, (int64_t)Win, Int<1>{}));
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout_per_group, kD, kH, kW),
      make_stride((int64_t)Cout_per_group * kD * kH * kW,
                  (int64_t)kD * kH * kW,
                  (int64_t)kH * kW,
                  (int64_t)kW,
                  Int<1>{}));
  const int KVOL = kD * kH * kW;
  const int total_w = OC_TILE * Cin_per_group * KVOL;
  const int IW_RANGE = TILE_W + kW - 1;
  T* sW_ptr = smem;
  T* sX_ptr = smem + total_w;
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(OC_TILE, Cin_per_group, kD, kH, kW),
      make_stride((int64_t)Cin_per_group * KVOL, (int64_t)KVOL,
                  (int64_t)kH * kW, (int64_t)kW, Int<1>{}));
  auto sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Cin_per_group, IW_RANGE),
      make_stride((int64_t)IW_RANGE, Int<1>{}));
  for (int idx = threadIdx.x; idx < total_w; idx += blockDim.x) {
    int oct_idx = idx / (Cin_per_group * KVOL);
    int rem0 = idx % (Cin_per_group * KVOL);
    int icl  = rem0 / KVOL;
    int krem = rem0 % KVOL;
    int kd = krem / (kH * kW);
    int kk = krem % (kH * kW);
    int kh = kk / kW;
    int kw = kk % kW;
    int ic = ic_base + icl;
    int oc_local = oc_local_base + oct_idx;
    sW(oct_idx, icl, kd, kh, kw) = mW(ic, oc_local, kd, kh, kw);
  }
  __syncthreads();
  const int ow = ow0 + (int)threadIdx.x;
  const bool valid_ow = ow < Wout;
  const int total_x = Cin_per_group * IW_RANGE;
  const int iw_base = ow0 + padW - (kW - 1);
  float acc[OC_TILE];
  #pragma unroll
  for (int t = 0; t < OC_TILE; ++t) acc[t] = 0.0f;
  for (int kd = 0; kd < kD; ++kd) {
    int id = od + padD - kd;
    bool id_valid = (id >= 0 && id < D);
    for (int kh = 0; kh < kH; ++kh) {
      int ih = oh + padH - kh;
      bool ih_valid = (ih >= 0 && ih < H);
      bool row_valid = id_valid && ih_valid;
      for (int idx = threadIdx.x; idx < total_x; idx += blockDim.x) {
        int icl = idx / IW_RANGE;
        int off = idx % IW_RANGE;
        T val = static_cast<T>(0);
        if (row_valid) {
          int iw = iw_base + off;
          if (iw >= 0 && iw < Win) {
            int ic = ic_base + icl;
            val = mX(ic, id, ih, iw);
          }
        }
        sX(icl, off) = val;
      }
      __syncthreads();
      if (valid_ow) {
        #pragma unroll
        for (int kw = 0; kw < kW; ++kw) {
          int off = (int)threadIdx.x + (kW - 1 - kw);
          #pragma unroll 4
          for (int icl = 0; icl < Cin_per_group; ++icl) {
            float xval = (float)sX(icl, off);
            #pragma unroll
            for (int t = 0; t < OC_TILE; ++t) {
              float wval = (float)sW(t, icl, kd, kh, kw);
              acc[t] += xval * wval;
            }
          }
        }
      }
      __syncthreads();
    }
  }
  if (valid_ow) {
    #pragma unroll
    for (int t = 0; t < OC_TILE; ++t) {
      float accv = acc[t];
      int oc_abs = oc_base + t;
      if (B != nullptr) {
        accv += (float)B[oc_abs];
      }
      T* y_ptr = Y + ((int64_t)n * Cout + oc_abs) * Dout * Hout * Wout
                   + ((int64_t)od * Hout + oh) * Wout + ow;
      *y_ptr = static_cast<T>(accv);
    }
  }
}
torch::Tensor convtranspose3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int opadD, int opadH, int opadW,
    int groups)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, kD, kH, kW]");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t D   = x_c.size(2);
  int64_t H   = x_c.size(3);
  int64_t Win = x_c.size(4);
  int64_t Cout_per_group = w_c.size(1);
  int64_t kD = w_c.size(2);
  int64_t kH = w_c.size(3);
  int64_t kW = w_c.size(4);
  int64_t Cout = Cout_per_group * groups;
  TORCH_CHECK(w_c.size(0) == Cin, "w.size(0) must equal Cin");
  int64_t Dout = (D - 1) * strideD - 2 * padD + kD + opadD;
  int64_t Hout = (H - 1) * strideH - 2 * padH + kH + opadH;
  int64_t Wout = (Win - 1) * strideW - 2 * padW + kW + opadW;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());
  int64_t Cin_per_group = Cin / groups;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  bool unit_stride = (strideD == 1 && strideH == 1 && strideW == 1);
  if (unit_stride) {
    const int TILE_W = 128;
    const int n_wtiles = (int)((Wout + TILE_W - 1) / TILE_W);
    int Cout_per_group_i = (int)Cout_per_group;
    int device = 0;
    cudaGetDevice(&device);
    int max_smem_optin = 0;
    cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
    auto smem_for_tile = [&](int tile) -> size_t {
      return (size_t)((int64_t)tile * Cin_per_group * kD * kH * kW
                       + Cin_per_group * (TILE_W + kW - 1)) * sizeof(float);
    };
    int oc_tile = 1;
    int oc_tile_candidates[4] = {8, 4, 2, 1};
    for (int ci = 0; ci < 4; ++ci) {
      int cand = oc_tile_candidates[ci];
      if (Cout_per_group_i % cand == 0 &&
          smem_for_tile(cand) <= (size_t)max_smem_optin) {
        oc_tile = cand;
        break;
      }
    }
    TORCH_CHECK(smem_for_tile(oc_tile) <= (size_t)max_smem_optin,
        "Required shared memory exceeds device limit even for oc_tile=1");
    dim3 block(TILE_W);
    dim3 grid(
        (unsigned)(Dout * Hout * n_wtiles),
        (unsigned)(Cout / oc_tile),
        (unsigned)N
    );
    size_t smem_bytes = (size_t)((int64_t)oc_tile * Cin_per_group * kD * kH * kW
                                  + Cin_per_group * (TILE_W + kW - 1)) * sizeof(float);
    if (oc_tile == 8) {
      cudaError_t attr_err8 = cudaFuncSetAttribute(
          convtranspose3d_kernel_tiled_s1<float, 128, 8>,
          cudaFuncAttributeMaxDynamicSharedMemorySize,
          (int)smem_bytes);
      TORCH_CHECK(attr_err8 == cudaSuccess, "cudaFuncSetAttribute failed (oc_tile=8): ", cudaGetErrorString(attr_err8));
      convtranspose3d_kernel_tiled_s1<float, 128, 8><<<grid, block, smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          b_ptr,
          y.data_ptr<float>(),
          (int)N, (int)Cin, (int)D, (int)H, (int)Win,
          (int)Cout, (int)kD, (int)kH, (int)kW,
          padD, padH, padW,
          groups,
          (int)Dout, (int)Hout, (int)Wout,
          n_wtiles
      );
    } else if (oc_tile == 4) {
      cudaError_t attr_err4 = cudaFuncSetAttribute(
          convtranspose3d_kernel_tiled_s1<float, 128, 4>,
          cudaFuncAttributeMaxDynamicSharedMemorySize,
          (int)smem_bytes);
      TORCH_CHECK(attr_err4 == cudaSuccess, "cudaFuncSetAttribute failed (oc_tile=4): ", cudaGetErrorString(attr_err4));
      convtranspose3d_kernel_tiled_s1<float, 128, 4><<<grid, block, smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          b_ptr,
          y.data_ptr<float>(),
          (int)N, (int)Cin, (int)D, (int)H, (int)Win,
          (int)Cout, (int)kD, (int)kH, (int)kW,
          padD, padH, padW,
          groups,
          (int)Dout, (int)Hout, (int)Wout,
          n_wtiles
      );
    } else if (oc_tile == 2) {
      cudaError_t attr_err2 = cudaFuncSetAttribute(
          convtranspose3d_kernel_tiled_s1<float, 128, 2>,
          cudaFuncAttributeMaxDynamicSharedMemorySize,
          (int)smem_bytes);
      TORCH_CHECK(attr_err2 == cudaSuccess, "cudaFuncSetAttribute failed (oc_tile=2): ", cudaGetErrorString(attr_err2));
      convtranspose3d_kernel_tiled_s1<float, 128, 2><<<grid, block, smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          b_ptr,
          y.data_ptr<float>(),
          (int)N, (int)Cin, (int)D, (int)H, (int)Win,
          (int)Cout, (int)kD, (int)kH, (int)kW,
          padD, padH, padW,
          groups,
          (int)Dout, (int)Hout, (int)Wout,
          n_wtiles
      );
    } else {
      cudaError_t attr_err1 = cudaFuncSetAttribute(
          convtranspose3d_kernel_tiled_s1<float, 128, 1>,
          cudaFuncAttributeMaxDynamicSharedMemorySize,
          (int)smem_bytes);
      TORCH_CHECK(attr_err1 == cudaSuccess, "cudaFuncSetAttribute failed (oc_tile=1): ", cudaGetErrorString(attr_err1));
      convtranspose3d_kernel_tiled_s1<float, 128, 1><<<grid, block, smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          b_ptr,
          y.data_ptr<float>(),
          (int)N, (int)Cin, (int)D, (int)H, (int)Win,
          (int)Cout, (int)kD, (int)kH, (int)kW,
          padD, padH, padW,
          groups,
          (int)Dout, (int)Hout, (int)Wout,
          n_wtiles
      );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "convtranspose3d_kernel_tiled_s1 launch failed: ", cudaGetErrorString(err));
  } else {
    const int Threads = 256;
    const int64_t P_total = Dout * Hout * Wout;
    dim3 block(Threads);
    dim3 grid(
        (unsigned)((P_total + Threads - 1) / Threads),
        (unsigned)Cout,
        (unsigned)N
    );
    size_t smem_bytes = (size_t)Cin_per_group * kD * kH * kW * sizeof(float);
    convtranspose3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)D, (int)H, (int)Win,
        (int)Cout, (int)kD, (int)kH, (int)kW,
        strideD, strideH, strideW,
        padD, padH, padW,
        groups,
        (int)Dout, (int)Hout, (int)Wout
    );
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "convtranspose3d_kernel launch failed: ", cudaGetErrorString(err));
  }
  return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_convtranspose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["convtranspose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with asymmetric kernel/stride/padding, implemented
    with a single custom CUDA kernel using CuTe tensors for indexing and
    shared-memory weight staging.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        # Use nn.ConvTranspose3d purely as a parameter container so that
        # initialization matches PyTorch's default scheme exactly.
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )

        self.stride = stride if isinstance(stride, tuple) else (stride, stride, stride)
        self.padding = padding if isinstance(padding, tuple) else (padding, padding, padding)
        self.output_padding = output_padding if isinstance(output_padding, tuple) else (output_padding, output_padding, output_padding)
        self.groups = groups

        self._ext = conv_transpose3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        return self._ext.convtranspose3d_forward(
            x.contiguous(),
            weight.contiguous(),
            bias if bias is not None else None,
            int(self.stride[0]), int(self.stride[1]), int(self.stride[2]),
            int(self.padding[0]), int(self.padding[1]), int(self.padding[2]),
            int(self.output_padding[0]), int(self.output_padding[1]), int(self.output_padding[2]),
            int(self.groups),
        )

